import React, { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "../ui/dialog";
import { Button } from "../ui/button";
import { Input } from "../ui/input";
import { Label } from "../ui/label";
import { Textarea } from "../ui/textarea";
import { Badge } from "../ui/badge";
import { Avatar, AvatarFallback } from "../ui/avatar";
import { Checkbox } from "../ui/checkbox";
import { VisuallyHidden } from "@radix-ui/react-visually-hidden";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../ui/tabs";
import {
  Clock,
  User,
  Calendar,
  Tag,
  MessageSquare,
  CheckSquare,
  Plus,
  X,
  Trash2,
  Send,
} from "lucide-react";
import { formatDate } from "../../utils/formatters";
import Swal from "sweetalert2";

const PRIORITY_OPTIONS = [
  { value: "low", label: "Baja", color: "bg-gray-100 text-gray-700" },
  { value: "medium", label: "Media", color: "bg-blue-100 text-blue-700" },
  { value: "high", label: "Alta", color: "bg-orange-100 text-orange-700" },
  { value: "urgent", label: "Urgente", color: "bg-red-100 text-red-700" },
];

const STATUS_OPTIONS = [
  { value: "todo", label: "Por Hacer" },
  { value: "in_progress", label: "En Progreso" },
  { value: "review", label: "En Revisión" },
  { value: "completed", label: "Completado" },
];

export const TaskDetailModal = ({
  isOpen,
  onClose,
  task,
  onUpdate,
  onDelete,
  teamMembers = [],
  readOnly = false,
}) => {
  const [editedTask, setEditedTask] = useState(task || {});
  const [newSubtask, setNewSubtask] = useState("");
  const [newTag, setNewTag] = useState("");
  const [newComment, setNewComment] = useState("");
  const [isEditing, setIsEditing] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);

  if (!task) return null;

  const handleSave = async () => {
    try {
      await onUpdate(editedTask);
      setIsEditing(false);
      Swal.fire({
        icon: "success",
        title: "Tarea Actualizada",
        text: "Los cambios han sido guardados",
        confirmButtonColor: "#16a34a",
        timer: 2000,
      });
    } catch (error) {
      Swal.fire({
        icon: "error",
        title: "Error",
        text: "No se pudo actualizar la tarea",
        confirmButtonColor: "#dc2626",
      });
    }
  };

  const handleDelete = async () => {
    const result = await Swal.fire({
      title: "¿Eliminar Tarea?",
      text: "Esta acción no se puede deshacer",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#dc2626",
      cancelButtonColor: "#6b7280",
      confirmButtonText: "Sí, eliminar",
      cancelButtonText: "Cancelar",
    });

    if (result.isConfirmed) {
      await onDelete(task._id);
      onClose();
      Swal.fire({
        icon: "success",
        title: "Tarea Eliminada",
        confirmButtonColor: "#16a34a",
        timer: 2000,
      });
    }
  };

  const addSubtask = () => {
    if (!newSubtask.trim()) return;

    const updatedTask = {
      ...editedTask,
      subtasks: [
        ...(editedTask.subtasks || []),
        {
          _id: Date.now().toString(),
          title: newSubtask,
          completed: false,
        },
      ],
    };
    setEditedTask(updatedTask);
    setNewSubtask("");
  };

  const toggleSubtask = (subtaskId) => {
    const updatedTask = {
      ...editedTask,
      subtasks: editedTask.subtasks.map((st) =>
        st._id === subtaskId ? { ...st, completed: !st.completed } : st
      ),
    };
    setEditedTask(updatedTask);
  };

  const removeSubtask = (subtaskId) => {
    const updatedTask = {
      ...editedTask,
      subtasks: editedTask.subtasks.filter((st) => st._id !== subtaskId),
    };
    setEditedTask(updatedTask);
  };

  const addTag = () => {
    if (!newTag.trim() || editedTask.tags?.includes(newTag)) return;

    const updatedTask = {
      ...editedTask,
      tags: [...(editedTask.tags || []), newTag],
    };
    setEditedTask(updatedTask);
    setNewTag("");
  };

  const removeTag = (tagToRemove) => {
    const updatedTask = {
      ...editedTask,
      tags: editedTask.tags.filter((t) => t !== tagToRemove),
    };
    setEditedTask(updatedTask);
  };

  const addComment = () => {
    if (!newComment.trim()) return;

    const comment = {
      _id: Date.now().toString(),
      content: newComment,
      user_id: { full_name: "Usuario Actual" }, // Esto vendría del contexto
      created_at: new Date().toISOString(),
    };

    const updatedTask = {
      ...editedTask,
      comments: [...(editedTask.comments || []), comment],
    };
    setEditedTask(updatedTask);
    setNewComment("");
  };

  const completedSubtasks =
    editedTask.subtasks?.filter((st) => st.completed).length || 0;
  const totalSubtasks = editedTask.subtasks?.length || 0;
  const progress =
    totalSubtasks > 0 ? (completedSubtasks / totalSubtasks) * 100 : 0;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <div className="flex items-start justify-between">
            <div className="flex-1">
              {isEditing ? (
                <Input
                  value={editedTask.title}
                  onChange={(e) =>
                    setEditedTask({ ...editedTask, title: e.target.value })
                  }
                  className="text-2xl font-bold mb-2"
                />
              ) : (
                <VisuallyHidden>
                  <DialogTitle className="text-2xl">
                    {editedTask.title}
                  </DialogTitle>
                </VisuallyHidden>
              )}

              <div className="flex flex-wrap gap-2 mt-2">
                <Badge
                  className={
                    PRIORITY_OPTIONS.find(
                      (p) => p.value === editedTask.priority
                    )?.color
                  }
                >
                  {
                    PRIORITY_OPTIONS.find(
                      (p) => p.value === editedTask.priority
                    )?.label
                  }
                </Badge>
                <Badge variant="outline">
                  {
                    STATUS_OPTIONS.find((s) => s.value === editedTask.status)
                      ?.label
                  }
                </Badge>
              </div>
            </div>

            {!readOnly && (
              <div className="flex gap-2">
                {isEditing ? (
                  <>
                    <Button
                      onClick={handleSave}
                      size="sm"
                      className="bg-green-600"
                    >
                      Guardar
                    </Button>
                    <Button
                      onClick={() => {
                        setEditedTask(task);
                        setIsEditing(false);
                      }}
                      variant="outline"
                      size="sm"
                    >
                      Cancelar
                    </Button>
                  </>
                ) : (
                  <>
                    <Button
                      onClick={() => setIsEditing(true)}
                      variant="outline"
                      size="sm"
                    >
                      Editar
                    </Button>
                    <Button
                      onClick={handleDelete}
                      variant="destructive"
                      size="sm"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </>
                )}
              </div>
            )}
          </div>
        </DialogHeader>

        <Tabs defaultValue="details" className="w-full">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="details">Detalles</TabsTrigger>
            <TabsTrigger value="subtasks">
              Subtareas
              {totalSubtasks > 0 && (
                <Badge variant="outline" className="ml-2">
                  {completedSubtasks}/{totalSubtasks}
                </Badge>
              )}
            </TabsTrigger>
            <TabsTrigger value="activity">Actividad</TabsTrigger>
          </TabsList>

          {/* Detalles Tab */}
          <TabsContent value="details" className="space-y-4">
            {/* Descripción */}
            <div>
              <Label>Descripción</Label>
              {isEditing ? (
                <Textarea
                  value={editedTask.description || ""}
                  onChange={(e) =>
                    setEditedTask({
                      ...editedTask,
                      description: e.target.value,
                    })
                  }
                  rows={4}
                  placeholder="Describe la tarea..."
                />
              ) : (
                <p className="text-sm text-gray-600 mt-2">
                  {editedTask.description || "Sin descripción"}
                </p>
              )}
            </div>

            <div className="grid grid-cols-2 gap-4">
              {/* Estado */}
              <div>
                <Label>Estado</Label>
                {isEditing ? (
                  <Select
                    value={editedTask.status}
                    onValueChange={(value) =>
                      setEditedTask({ ...editedTask, status: value })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {STATUS_OPTIONS.map((option) => (
                        <SelectItem key={option.value} value={option.value}>
                          {option.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                ) : (
                  <p className="text-sm text-gray-600 mt-2">
                    {
                      STATUS_OPTIONS.find((s) => s.value === editedTask.status)
                        ?.label
                    }
                  </p>
                )}
              </div>

              {/* Prioridad */}
              <div>
                <Label>Prioridad</Label>
                {isEditing ? (
                  <Select
                    value={editedTask.priority}
                    onValueChange={(value) =>
                      setEditedTask({ ...editedTask, priority: value })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {PRIORITY_OPTIONS.map((option) => (
                        <SelectItem key={option.value} value={option.value}>
                          {option.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                ) : (
                  <p className="text-sm text-gray-600 mt-2">
                    {
                      PRIORITY_OPTIONS.find(
                        (p) => p.value === editedTask.priority
                      )?.label
                    }
                  </p>
                )}
              </div>

              {/* Asignado a */}
              <div>
                <Label>Asignado a</Label>
                {isEditing ? (
                  <Select
                    value={editedTask.assigned_to?._id || ""}
                    onValueChange={(value) => {
                      const member = teamMembers.find((m) => m._id === value);
                      setEditedTask({ ...editedTask, assigned_to: member });
                    }}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Seleccionar..." />
                    </SelectTrigger>
                    <SelectContent>
                      {teamMembers.map((member) => (
                        <SelectItem key={member._id} value={member._id}>
                          {member.full_name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                ) : (
                  <div className="flex items-center space-x-2 mt-2">
                    {editedTask.assigned_to ? (
                      <>
                        <Avatar className="h-6 w-6">
                          <AvatarFallback className="text-xs">
                            {editedTask.assigned_to.full_name
                              ?.split(" ")
                              .map((n) => n[0])
                              .join("")}
                          </AvatarFallback>
                        </Avatar>
                        <span className="text-sm text-gray-600">
                          {editedTask.assigned_to.full_name}
                        </span>
                      </>
                    ) : (
                      <span className="text-sm text-gray-400">Sin asignar</span>
                    )}
                  </div>
                )}
              </div>

              {/* Fecha límite */}
              <div>
                <Label>Fecha límite</Label>
                {isEditing ? (
                  <Input
                    type="date"
                    value={
                      editedTask.due_date
                        ? new Date(editedTask.due_date)
                            .toISOString()
                            .split("T")[0]
                        : ""
                    }
                    onChange={(e) =>
                      setEditedTask({ ...editedTask, due_date: e.target.value })
                    }
                  />
                ) : (
                  <p className="text-sm text-gray-600 mt-2">
                    {editedTask.due_date
                      ? formatDate(editedTask.due_date)
                      : "Sin fecha"}
                  </p>
                )}
              </div>
            </div>

            {/* Tags */}
            <div>
              <Label>Etiquetas</Label>
              <div className="flex flex-wrap gap-2 mt-2">
                {editedTask.tags?.map((tag, idx) => (
                  <Badge
                    key={idx}
                    variant="outline"
                    className="flex items-center gap-1"
                  >
                    {tag}
                    {isEditing && (
                      <X
                        className="w-3 h-3 cursor-pointer"
                        onClick={() => removeTag(tag)}
                      />
                    )}
                  </Badge>
                ))}
                {isEditing && (
                  <div className="flex gap-2">
                    <Input
                      placeholder="Nueva etiqueta"
                      value={newTag}
                      onChange={(e) => setNewTag(e.target.value)}
                      onKeyPress={(e) => e.key === "Enter" && addTag()}
                      className="w-32"
                    />
                    <Button onClick={addTag} size="sm">
                      <Plus className="w-4 h-4" />
                    </Button>
                  </div>
                )}
              </div>
            </div>
          </TabsContent>

          {/* Subtareas Tab */}
          <TabsContent value="subtasks" className="space-y-4">
            {/* Progress bar */}
            {totalSubtasks > 0 && (
              <div className="mb-4">
                <div className="flex justify-between text-sm mb-2">
                  <span>Progreso</span>
                  <span>{Math.round(progress)}%</span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-2">
                  <div
                    className="bg-green-500 h-2 rounded-full transition-all"
                    style={{ width: `${progress}%` }}
                  />
                </div>
              </div>
            )}

            {/* Lista de subtareas */}
            <div className="space-y-2">
              {editedTask.subtasks?.map((subtask) => (
                <div
                  key={subtask._id}
                  className="flex items-center justify-between p-3 bg-gray-50 rounded-lg"
                >
                  <div className="flex items-center space-x-3 flex-1">
                    <Checkbox
                      checked={subtask.completed}
                      onCheckedChange={() =>
                        !readOnly && toggleSubtask(subtask._id)
                      }
                      disabled={readOnly}
                    />
                    <span
                      className={`text-sm ${
                        subtask.completed
                          ? "line-through text-gray-400"
                          : "text-gray-700"
                      }`}
                    >
                      {subtask.title}
                    </span>
                  </div>
                  {isEditing && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => removeSubtask(subtask._id)}
                    >
                      <X className="w-4 h-4 text-red-600" />
                    </Button>
                  )}
                </div>
              ))}
            </div>

            {/* Agregar subtarea */}
            {!readOnly && (
              <div className="flex gap-2">
                <Input
                  placeholder="Nueva subtarea"
                  value={newSubtask}
                  onChange={(e) => setNewSubtask(e.target.value)}
                  onKeyPress={(e) => e.key === "Enter" && addSubtask()}
                />
                <Button onClick={addSubtask}>
                  <Plus className="w-4 h-4" />
                </Button>
              </div>
            )}
          </TabsContent>

          {/* Actividad Tab */}
          <TabsContent value="activity" className="space-y-4">
            {/* Comentarios */}
            <div className="space-y-4">
              {editedTask.comments?.map((comment) => (
                <div key={comment._id} className="bg-gray-50 p-4 rounded-lg">
                  <div className="flex items-start space-x-3">
                    <Avatar className="h-8 w-8">
                      <AvatarFallback className="text-xs">
                        {comment.user_id?.full_name
                          ?.split(" ")
                          .map((n) => n[0])
                          .join("")}
                      </AvatarFallback>
                    </Avatar>
                    <div className="flex-1">
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-semibold text-sm">
                          {comment.user_id?.full_name}
                        </span>
                        <span className="text-xs text-gray-500">
                          {formatDate(comment.created_at)}
                        </span>
                      </div>
                      <p className="text-sm text-gray-700">{comment.content}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>

            {/* Agregar comentario */}
            {!readOnly && (
              <div className="flex gap-2">
                <Textarea
                  placeholder="Escribe un comentario..."
                  value={newComment}
                  onChange={(e) => setNewComment(e.target.value)}
                  rows={3}
                />
                <Button onClick={addComment} className="flex-shrink-0">
                  <Send className="w-4 h-4" />
                </Button>
              </div>
            )}
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
};
